    'web.landing.heroPrimaryCta': '最初のエージェントを作成する',
    'web.landing.faqQ1': 'これは Claude / Codex の別のラッパーですか？',
    'web.landing.faqA1': 'いいえ。Manyfold は、添付ファイル、端末状態、再開可能なセッションを備えた分離ワークスペースで、実際のエージェントランタイム (Claude Code、Codex、Gemini CLI) をホストします。プロバイダーキーはあなたが用意するだけで、実行ループは私たちが担います。',
    'web.landing.faqQ2': 'サンドボックスとクラウド コンピューターの違いは何ですか？',
    'web.landing.faqA2': 'サンドボックスは耐久性がありながらオンデマンドです。エージェントがファイル、ターミナル、後で選択できるセッションを必要とするリポジトリ タスクに最適です。クラウド コンピューターは、cron ジョブ、コネクタ、およびスリープしてはいけないサービスのためにオンラインを維持します。',
    'web.landing.faqQ3': '自分のプロバイダー キーを持参する必要がありますか？',
    'web.landing.faqA3': '可能です。キーはワークスペースごとに保存され、エージェントごとに振り分けられます。Claude Code は Anthropic に、Codex のジョブは OpenAI に、Gemini CLI のセッションは Google に送られます。いずれも従量制アクセスを使用できます。',
    'web.landing.faqQ4': '独自のフレームワーク エージェントを使用できますか？',
    'web.landing.faqA4': 'はい。OpenClaw および Hermes はファーストクラスであり、Linux で実行され、CLI エントリ ポイントを持つフレームワークはすべて、カスタム エージェント定義としてホストできます。',
    'web.landing.faqQ5': '価格設定はどのように行われますか？',
    'web.landing.faqA5': 'ワークスペースの定額料金には、レール、セッション、および 1 つのステートフル サンドボックスが含まれます。クラウド コンピューターとプロバイダー トークンは従量制です。座席当たりの税金はかかりません。',
