    'web.channels.settings.connection.websocket': 'WebSocket（長時間接続）',
    'web.channels.settings.connectionHelp.matrix': 'API は bot のアクセス トークンを使って Matrix の /sync をポーリングします — 公開 URL やコールバック設定は不要です。暗号化されたルームには対応しておらず、暗号化イベントは破棄されます。',
    'web.channels.settings.connectionHelp.discord': 'API は Discord Gateway への接続を保持します — 公開 URL やコールバック設定は不要です。デベロッパーポータルの Bot → Privileged Gateway Intents で MESSAGE_CONTENT が有効になっていることを確認してください。',
    'web.channels.settings.connectionHelp.weixin': 'API は bot トークンを使って Tencent iLink bot ゲートウェイをロングポーリングします — 公開 URL は不要です。個人の WeChat はダイレクトメッセージのみに対応し、グループチャットは配信されません。セッションが期限切れ（errcode -14）になった場合は、QR コードを再スキャンしてトークンを更新してください。',
    'web.channels.settings.webhookHelp.telegram': '認証情報を保存すると Telegram の Webhook が自動的に登録されます — 貼り付ける必要はありません。',
    'web.channels.settings.webhookHelp.slack': 'この URL を Slack アプリの「Event Subscriptions」→「Request URL」に貼り付けてください。',
    'web.channels.settings.webhookHelp.lark': 'これを {{platform}} の Open Platform → Event Subscriptions → Request URL に貼り付けてください。',
    'web.channels.settings.webhookHelp.github': 'GitHub App の作成フローでは、この Webhook URL がアプリに自動的に設定されます。手動で作成したアプリの場合は、issues および issue_comment イベントを含むアプリの Webhook URL として設定してください。',
    'web.channels.settings.webhookHelp.other': 'この URL をプロバイダーのイベント サブスクリプション設定に貼り付けてください。',
    'web.channels.settings.webhookHelp.line': '認証情報を保存すると LINE の Webhook URL は自動で設定されます — 貼り付けるものはありません。LINE Developers コンソールの Messaging API で「Webhookの利用」をオンにし、応答メッセージ（自動応答）をオフにしてください。オンのままだとボットが二重に返信します。',
    'web.channels.settings.github.title': 'GitHub App',
    'web.channels.settings.github.connectedAs': '接続済み:',
    'web.channels.settings.github.mentionHint': '。issue やコメントでメンションすると、ターンが開始されます。',
    'web.channels.settings.github.install': 'リポジトリにインストール',
    'web.channels.settings.github.installHint': 'エージェントが応答すべきすべてのリポジトリにアプリをインストールする必要があります。リポジトリへの書き込みアクセス（clone/push/PR）は、同じエージェントにリンクされた GitHub 接続から提供され、このアプリからは提供されません。',
    'web.channels.settings.github.createHint': 'このチャンネル専用の GitHub App を作成します — GitHub が自動的に認証情報を返し、チャンネルが自動的に有効化されます。個人アカウントで作成する場合は組織を空欄のままにしてください。',
