    'web.channels.settings.help.telegramCreate': '@BotFather 経由で bot を作成し、トークンを貼り付けてください。Webhook はこちらで代理登録します。',
    'web.channels.settings.help.telegramEdit': '許可するユーザーやグループチャットを空欄のままにすると、誰でも利用できます。オペレーターは /model のようなエージェント全体のコマンドを実行できます。オペレーターがいない場合、それらのコマンドは Telegram から無効になります。',
    'web.channels.settings.help.slackCreate': '保存後、チャンネルの受信 URL を Slack アプリの Event Subscriptions に貼り付けてください。許可するユーザーを空欄のままにすると、ワークスペース内の誰でも bot を使用できます。オペレーターは /model のようなエージェント全体のコマンドを実行できます。オペレーターがいない場合、Slack から /model は無効になります。',
    'web.channels.settings.help.slackEdit': '許可するユーザーを空欄のままにすると、ワークスペース内の誰でも bot を使用できます。オペレーターは /model のようなエージェント全体のコマンドを実行できます。オペレーターがいない場合、Slack から /model は無効になります。',
    'web.channels.settings.help.linearCreate': 'あなたの Linear ワークスペースでアプリケーションを作成し、Agent session イベント付きで Webhook を有効化した上で、保存後にチャンネルの受信 URL をそこに貼り付けてください。クライアント認証情報を使うと Manyfold が独自のアプリトークンを発行します。自分でトークンを発行した場合はアクセストークンを代わりに指定してください。許可するユーザーを空欄のままにすると、ワークスペース内の誰でもエージェントにメンションできます。',
    'web.channels.settings.help.githubCreate': 'まずチャンネルを作成し、そのページで「GitHub App を作成」を使用してください — GitHub がアプリの認証情報を自動的に返します。issue でアプリにメンションするとターンが開始されます。リポジトリを空欄のままにすると、アプリがインストールされているすべてのリポジトリに応答します。',
    'web.channels.settings.help.discordCreate': 'Discord は Gateway WebSocket を使用するため、公開 URL は不要です。デベロッパーポータルの Bot → Privileged Gateway Intents で MESSAGE_CONTENT インテントを有効にしてください。そうしないと bot はメッセージのテキストを認識できません。',
    'web.channels.settings.help.matrixCreate': 'Matrix は /sync のロングポーリングを使用するため、Webhook URL は不要です。暗号化されたルームには対応しておらず、暗号化イベントは破棄されます。',
    'web.channels.settings.help.weixinCreate': '個人の WeChat は Tencent iLink bot ゲートウェイ経由で、ダイレクトメッセージのみに対応し、Webhook URL は不要です。エージェント全体のコマンドを無効にするには、オペレーター ID を空欄のままにしてください。',
    'web.channels.settings.help.larkManual': '許可するユーザーを空欄のままにすると、誰でも bot にアクセスできます。オペレーターは /model のようなエージェント全体のコマンドを実行できます。オペレーターがいない場合、Feishu/Lark から /model は無効になります。',
    'web.channels.settings.help.weixinEdit': '個人の WeChat はダイレクトメッセージのみに対応します。エージェント全体のコマンド（/model など）を無効にするには、オペレーター ID を空欄のままにしてください。',
    'web.channels.settings.help.whatsappEdit': 'WhatsApp は WhatsApp Web 経由で連携するため、このチャネルに webhook URL は不要です。許可する送信者やグループチャットを空にすると制限しません。オペレーターは /model などのエージェント全体のコマンドを実行できます。オペレーターがいない場合、これらのコマンドは WhatsApp では無効です。送信者は電話番号または jid で指定できます。',
    'web.channels.settings.help.linearEdit': 'アクティビティは、エージェントが作業している間、思考過程・ツール呼び出し・計画を Linear のセッションに表示します。最終結果のみの場合は結果のみを投稿します。認証情報のローテーションはすべてを一括で置き換えるため、変更のたびに署名シークレットを再入力してください。',
    'web.channels.settings.help.githubEdit': '許可するログイン名を空欄のままにすると、関係性によるゲート（デフォルトではリポジトリ所有者、組織メンバー、コラボレーター — 制限をなくすには NONE を追加）にフォールバックします。issue に委任ラベルを付けると、メンションなしでターンが開始されます。エージェント全体のコマンド（/model など）を無効にするには、オペレーターのログイン名を空欄のままにしてください。',
    'web.channels.settings.help.lineCreate': 'LINE Developers コンソールで Messaging API チャネルを作成し、長期のチャネルアクセストークンを発行して、両方をここに貼り付けてください。Webhook URL はこちらで設定しますが、「Webhookの利用」はコンソールでご自身でオンにする必要があります。返信はプレーンテキストでライブプレビューはなく、1 通ごとに LINE プランのメッセージ通数を消費します。',
    'web.channels.settings.help.lineEdit': '許可するユーザーやグループ ID を空欄にすると全員が利用できます。オペレーターは /model などのエージェント全体のコマンドを実行できます。オペレーターがいない場合、これらのコマンドは LINE では無効です。認証情報のローテーションは両方を一度に置き換えるため、チャネルシークレットとアクセストークンを一緒に入力し直してください。',
    'web.channels.settings.errors.larkWebhookCredentials': 'Lark/Feishu の Webhook チャンネルには検証トークンまたは暗号化キーが必要です。',
    'web.channels.settings.errors.linearCredentials': 'Linear にはアクセス トークン、またはクライアント ID とクライアント シークレットの両方のいずれかが必要です',
    'web.channels.settings.errors.matrixHomeserver': 'Matrix のホームサーバー URL は必須です。',
    'web.channels.settings.errors.matrixAccessToken': 'Matrix のアクセス トークンは必須です。',
    'web.channels.settings.errors.slackCredentials': 'Slack のトークンローテーションには Bot トークンと署名シークレットの両方が必要です。',
    'web.channels.settings.errors.linearRotation': 'Linear の認証情報ローテーションには Webhook 署名シークレットに加えて、アクセス トークン、またはクライアント ID とクライアント シークレットの両方のいずれかが必要です。',
    'web.channels.settings.errors.githubRotation': 'GitHub の認証情報ローテーションには App ID、秘密鍵、Webhook シークレットがすべて必要です。',
    'web.channels.settings.errors.weixinBotToken': 'WeChat の iLink bot トークンは必須です。',
